import threading

class ZeroEvenOdd:
    def __init__(self, n):
        self.n = n
        self.i = 1
        self.sZero = threading.Semaphore(1)
        self.sEven = threading.Semaphore(0)
        self.sOdd = threading.Semaphore(0)

    def zero(self, printNumber):
        for _ in range(self.n):
            self.sZero.acquire()
            printNumber(0)
            if self.i % 2 == 1:
                self.sOdd.release()
            else:
                self.sEven.release()

    def even(self, printNumber):
        while self.i <= self.n:
            self.sEven.acquire()
            printNumber(self.i)
            self.i += 1
            self.sZero.release()

    def odd(self, printNumber):
        while self.i <= self.n:
            self.sOdd.acquire()
            printNumber(self.i)
            self.i += 1
            self.sZero.release()

