import threading

class ZeroEvenOdd:
    def __init__(self, n):
        self.n = n
        self.i = 1
        self.state = 0
        self.cv = threading.Condition()

    def zero(self, printNumber):
        with self.cv:
            for _ in range(self.n):
                while self.state != 0:
                    self.cv.wait()
                printNumber(0)
                self.state = 1 if self.i % 2 == 1 else 2
                self.cv.notify_all()

    def even(self, printNumber):
        with self.cv:
            while self.i <= self.n:
                while self.state != 2:
                    self.cv.wait()
                printNumber(self.i)
                self.i += 1
                self.state = 0
                self.cv.notify_all()

    def odd(self, printNumber):
        with self.cv:
            while self.i <= self.n:
                while self.state != 1:
                    self.cv.wait()
                printNumber(self.i)
                self.i += 1
                self.state = 0
                self.cv.notify_all()

