var ZeroEvenOdd = function(n) {
    this.n = n;
    this.i = 1;
    this.state = 0;
    this.resolvers = [];
};

ZeroEvenOdd.prototype.signal = function() {
    const rs = this.resolvers;
    this.resolvers = [];
    rs.forEach(r => r());
};

ZeroEvenOdd.prototype.waitFor = function(s) {
    return new Promise(res => {
        if (this.state === s) res();
        else {
            this.resolvers.push(() => {
                if (this.state === s) res();
                else this.resolvers.push(arguments.callee);
            });
        }
    });
};

ZeroEvenOdd.prototype.zero = async function(printNumber) {
    for (let k = 0; k < this.n; k++) {
        while (this.state !== 0) await new Promise(r => this.resolvers.push(r));
        printNumber(0);
        this.state = (this.i % 2 === 1) ? 1 : 2;
        this.signal();
    }
};

ZeroEvenOdd.prototype.even = async function(printNumber) {
    while (this.i <= this.n) {
        while (this.state !== 2) await new Promise(r => this.resolvers.push(r));
        printNumber(this.i);
        this.i++;
        this.state = 0;
        this.signal();
    }
};

